<script setup>
import {computed,nextTick,onMounted,reactive,ref} from 'vue'
import {call,setCSRF} from './api'
import DataTable from './components/DataTable.vue'
import {Button as UiButton} from './components/ui/button'
import {Input as UiInput} from './components/ui/input'
import {Textarea as UiTextarea} from './components/ui/textarea'
import {Card as UiCard} from './components/ui/card'
import UiSelect from './components/ui/select/Select.vue'

const api=(name,args={},write=false)=>call('lotus_farm.warehouse.'+name,args,write)
const session=ref(null),data=ref(null),company=ref(''),warehouse=ref(''),search=ref(''),start=ref(0),tab=ref('stock')
const busy=ref(false),saving=ref(false),error=ref(''),saved=ref(null),dialog=ref(null)
const masterDialog=ref(null),masterKind=ref('item'),masterBusy=ref(false),masterError=ref(''),catalog=ref({groups:[],uoms:[],parents:[]})
const master=reactive({name:'',code:'',group:'',uom:'',parent:'',description:'',new_group:'',group_parent:''})
const masterTitles={item:'Thêm vật tư',group:'Thêm nhóm vật tư',warehouse:'Thêm kho'}
const commonUnits={Kg:'kg',Gram:'g',Litre:'Lít',Millilitre:'ml',Nos:'Cái',Box:'Hộp / thùng',Pair:'Đôi',Meter:'Mét',Tonne:'Tấn',Unit:'Đơn vị'}
const popularUoms=computed(()=>Object.keys(commonUnits).filter(name=>catalog.value.uoms.some(u=>u.name===name)))
const detailDialog=ref(null),detail=ref(null),detailError=ref(''),posting=ref(false),confirmPost=ref(false)
const kinds={receipt:'Nhập kho',issue:'Xuất dùng',transfer:'Chuyển kho',count:'Kiểm kê'}
const form=reactive({kind:'receipt',count_purpose:'Stock Reconciliation',posting_date:'',source:'',target:'',notes:'',lines:[],issue_mode:'Manual',work_plan:'',receiver:''})
const issueTabs={Manual:'Thủ công',Plan:'Theo kế hoạch đã duyệt',Request:'Theo yêu cầu đã duyệt'}
const issueSources=ref([]),issueSource=ref(''),issueNote=ref(''),issueLoading=ref(false)
let issueVersion=0
const fmt=n=>Number(n||0).toLocaleString('vi-VN',{maximumFractionDigits:3})
const needsSource=computed(()=>['issue','transfer'].includes(form.kind))
const needsTarget=computed(()=>['receipt','transfer','count'].includes(form.kind))
const canCreate=computed(()=>!!company.value&&!!data.value?.warehouses.length)
const stocks=computed(()=>data.value?.items||[])
const money=computed(()=>data.value?.currency||'')
let version=0
async function refresh(reset=false){
 if(reset)start.value=0
 if(!company.value){data.value=null;return}
 const request=++version;busy.value=true;error.value=''
 try{const result=await api('overview',{company:company.value,warehouse:warehouse.value,search:search.value,start:start.value});if(request===version)data.value=result}
 catch(e){if(request===version){data.value=null;error.value=e.message}}
 finally{if(request===version)busy.value=false}
}
async function initialize(){busy.value=true;try{session.value=await api('bootstrap');setCSRF(session.value.csrf_token);company.value=session.value.companies[0]?.name||'';form.posting_date=session.value.today;await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
function companyChanged(){warehouse.value='';saved.value=null;data.value=null;refresh(true)}
async function open(kind){issueVersion++;error.value='';saved.value=null;form.kind=kind;form.issue_mode='Manual';form.work_plan='';form.receiver='';issueSource.value='';issueSources.value=[];issueNote.value='';issueLoading.value=false;form.count_purpose='Stock Reconciliation';form.posting_date=session.value.today;form.source=warehouse.value||data.value.warehouses[0]?.name||'';form.target=kind==='transfer'?'':form.source;form.notes='';form.lines=[{item:'',qty:kind==='count'?0:1,area:''}];await nextTick();dialog.value.showModal()}
function chooseItem(row){const item=stocks.value.find(i=>i.name===row.item);if(form.kind==='count'&&warehouse.value)row.qty=item?.actual_qty||0}
async function changeIssueMode(mode){const version=++issueVersion;form.issue_mode=mode;form.work_plan='';issueSource.value='';issueSources.value=[];issueNote.value='';error.value='';form.lines=mode==='Manual'?[{item:'',qty:1,area:''}]:[];issueLoading.value=mode!=='Manual';if(mode==='Manual')return;try{const result=await api('issue_sources',{company:company.value,mode});if(version===issueVersion){issueSources.value=result.rows;issueNote.value=result.note}}catch(e){if(version===issueVersion)error.value=e.message}finally{if(version===issueVersion)issueLoading.value=false}}
async function selectIssueSource(){const version=++issueVersion;form.lines=[];form.work_plan=form.issue_mode==='Plan'?issueSource.value:'';if(!issueSource.value)return;issueLoading.value=true;error.value='';try{const result=await api('issue_lines',{company:company.value,mode:form.issue_mode,name:issueSource.value});if(version===issueVersion){form.lines=result.rows.map(r=>({...r,qty:r.remaining_qty,fixed_area:!!r.area}));issueNote.value=result.note}}catch(e){if(version===issueVersion)error.value=e.message}finally{if(version===issueVersion)issueLoading.value=false}}
async function save(){
 if(saving.value)return
 saving.value=true;error.value=''
 try{const lines=form.kind==='issue'&&form.issue_mode!=='Manual'?form.lines.filter(r=>Number(r.qty)>0):form.lines;if(!lines.length)throw new Error('Chọn ít nhất một dòng vật tư có số lượng cấp lớn hơn 0.');saved.value=await api('create_draft',{company:company.value,...form,lines},true);dialog.value.close();tab.value='history';await refresh();await openDocument(saved.value.doctype,saved.value.name)}
 catch(e){error.value=e.message}
 finally{saving.value=false}
}
const status=s=>['Nháp','Đã ghi sổ','Đã hủy'][s]||s
const type=t=>({'Material Receipt':'Nhập kho','Material Issue':'Xuất dùng','Material Transfer':'Chuyển kho','Repack':'Đóng gói'})[t]||t
async function openMaster(kind){
 masterError.value='';error.value='';masterKind.value=kind
 try{catalog.value=await api('catalogue',{company:company.value});const root=catalog.value.groups.find(g=>g.is_group&&!g.parent_item_group)?.name||catalog.value.groups.find(g=>g.is_group)?.name||''
 Object.assign(master,{name:'',code:'',group:'',uom:catalog.value.uoms.find(u=>u.name==='Kg')?.name||catalog.value.uoms[0]?.name||'',parent:kind==='warehouse'?catalog.value.parents[0]?.name||'':root,description:'',new_group:'',group_parent:root});await nextTick();masterDialog.value.showModal()}
 catch(e){error.value=e.message}
}
async function saveMaster(){if(masterBusy.value)return;masterBusy.value=true;masterError.value=''
 try{const result=await api('create_master',{company:company.value,kind:masterKind.value,values:{...master}},true);masterDialog.value.close();saved.value={name:result.name,master:true};if(masterKind.value==='item'){search.value='';start.value=0}await refresh();catalog.value=await api('catalogue',{company:company.value})}
 catch(e){masterError.value=e.message}finally{masterBusy.value=false}
}
async function openDocument(doctype,name){error.value='';detailError.value='';confirmPost.value=false;try{detail.value=await api('document',{doctype,name});await nextTick();detailDialog.value.showModal()}catch(e){error.value=e.message}}
async function postDocument(){if(posting.value||!confirmPost.value)return;posting.value=true;detailError.value='';try{await api('submit_document',{doctype:detail.value.doctype,name:detail.value.name},true);detail.value=await api('document',{doctype:detail.value.doctype,name:detail.value.name});confirmPost.value=false;await refresh()}catch(e){detailError.value=e.message}finally{posting.value=false}}

const stockColumns=[{field:'item_name',headerName:'Vật tư',minWidth:240,flex:2},{field:'name',headerName:'Mã vật tư',minWidth:210},{field:'item_group',headerName:'Nhóm'},{field:'stock_uom',headerName:'Đơn vị',minWidth:100},{field:'actual_qty',headerName:'Tồn hiện tại',type:'numericColumn',filter:'agNumberColumnFilter',valueFormatter:p=>fmt(p.value)},{headerName:'Trạng thái',valueGetter:p=>p.data.actual_qty>0?'Có tồn':p.data.actual_qty<0?'Tồn âm':'Chưa có tồn'}]
const historyRows=computed(()=>[...(data.value?.entries||[]).map(r=>({...r,doctype:'Stock Entry',kind:type(r.stock_entry_type)})),...(data.value?.reconciliations||[]).map(r=>({...r,doctype:'Stock Reconciliation',kind:'Kiểm kê'}))].sort((a,b)=>b.posting_date.localeCompare(a.posting_date)))
const historyColumns=[{field:'name',headerName:'Mã phiếu',minWidth:230,flex:2},{field:'kind',headerName:'Nghiệp vụ'},{field:'posting_date',headerName:'Ngày'},{field:'docstatus',headerName:'Trạng thái',valueFormatter:p=>status(p.value)}]
const detailColumns=[{headerName:'Vật tư',minWidth:220,flex:2,valueGetter:p=>p.data.item_name||p.data.item},{field:'item',headerName:'Mã vật tư'},{field:'qty',headerName:'Số lượng',type:'numericColumn',valueFormatter:p=>fmt(p.value)},{field:'uom',headerName:'Đơn vị'},{field:'area',headerName:'Khu vực / lô'},{headerName:'Kho xuất / nhận',minWidth:220,valueGetter:p=>[p.data.source,p.data.target].filter(Boolean).join(' → ')}]

onMounted(initialize)
</script>

<template>
 <div class="stock-shell">
  <aside class="stock-sidebar"><a class="stock-brand" href="/lotus/mobile"><span class="stock-logo">L</span><span>LOTUS<small>QUẢN LÝ NÔNG TRƯỜNG</small></span></a><p class="stock-nav-label">KHÔNG GIAN LÀM VIỆC</p><nav aria-label="Quản lý kho"><UiButton variant="outline" :class="{selected:tab==='stock'}" @click="tab='stock'">▦ <span>Tồn kho</span></UiButton><UiButton variant="outline" :class="{selected:tab==='history'}" @click="tab='history'">▤ <span>Phiếu nhập · xuất</span></UiButton><UiButton variant="outline" :class="{selected:tab==='setup'}" @click="tab='setup'">⚙ <span>Thiết lập kho</span></UiButton></nav><div class="stock-sidebar-bottom"><a href="/lotus/mobile">← Về Lotus Farm</a><small>{{session?.user||'Đang kết nối…'}}</small></div></aside>
  <main class="stock-main">
   <header class="stock-header"><div><p class="stock-kicker">LOTUS / KHO VẬT TƯ</p><h1>{{tab==='stock'?'Quản lý kho':tab==='history'?'Phiếu nhập · xuất':'Thiết lập kho'}}</h1><p class="stock-muted">{{tab==='stock'?'Vật tư sẵn có, rõ từng kho.':tab==='history'?'Theo dõi phiếu và mở chi tiết để duyệt.':'Bắt đầu từ danh mục và các kho của farm.'}}</p></div><UiButton variant="outline" class="stock-button" :disabled="busy" @click="refresh()">{{busy?'Đang tải…':'↻ Làm mới'}}</UiButton></header>
   <p v-if="error&&!dialog?.open" class="stock-error" role="alert">{{error}}</p>
   <p v-if="saved" class="stock-success" role="status">{{saved.master?"Đã thêm":"Đã lưu nháp"}} <strong>{{saved.name}}</strong>. <UiButton variant="ghost" v-if="!saved.master" class="stock-text-button" @click="openDocument(saved.doctype,saved.name)">Xem phiếu →</UiButton></p>
   <div class="stock-scope"><label>Công ty<UiSelect v-model="company" @change="companyChanged"><option v-if="!session?.companies.length" value="">Chưa có công ty</option><option v-for="c in session?.companies" :key="c.name" :value="c.name">{{c.name}}</option></UiSelect></label><label>Kho<UiSelect v-model="warehouse" :disabled="!company||busy" @change="refresh(true)"><option value="">Tất cả kho được phân quyền</option><option v-for="w in data?.warehouses" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label></div>
   <section v-if="!busy&&session&&(!company||!data?.warehouses.length||!stocks.length)&&tab==='stock'" class="stock-welcome"><div class="stock-welcome-icon">▦</div><div><p class="stock-kicker">BẮT ĐẦU CHO FARM MỚI</p><h2>Kho mới, sẵn sàng từ bước đầu tiên.</h2><p>Tạo công ty, khai báo kho và vật tư. Khi hàng về, lập phiếu nhập để bắt đầu theo dõi tồn.</p><UiButton variant="default" class="stock-button primary" @click="tab='setup'">Thiết lập kho của bạn →</UiButton></div></section>
   <section v-if="tab==='stock'" class="stock-actions" aria-label="Thao tác kho"><UiButton variant="outline" v-for="(title,kind) in kinds" :key="kind" :disabled="!canCreate||!session?.permissions[kind==='count'?'Stock Reconciliation':'Stock Entry']||busy" @click="open(kind)"><span>{{{receipt:'↓',issue:'↑',transfer:'⇄',count:'✓'}[kind]}}</span><strong>{{title}}</strong><small>{{{receipt:'Hàng về kho',issue:'Cấp vật tư sử dụng',transfer:'Giữa các kho',count:'Đối chiếu thực tế'}[kind]}}</small></UiButton></section>
   <template v-if="tab==='stock'">
    <div class="stock-metrics"><UiCard><small>Kho đang hoạt động</small><strong>{{data?.warehouses.length??'—'}}</strong></UiCard><UiCard><small>Vật tư trong trang</small><strong>{{data?stocks.length:'—'}}</strong></UiCard><UiCard><small>Có tồn · trong trang</small><strong>{{data?stocks.filter(i=>i.actual_qty>0).length:'—'}}</strong></UiCard></div>
    <section class="stock-panel"><div class="stock-panel-head"><div><h2>Danh sách vật tư</h2><p>{{warehouse||'Tổng tồn trong các kho được phân quyền'}} · Số lượng theo đơn vị của từng vật tư</p></div><UiButton variant="outline" v-if="session?.permissions.Item" class="stock-button" :disabled="!company" @click="openMaster('item')">+ Thêm vật tư</UiButton><form class="stock-search" @submit.prevent="refresh(true)"><UiInput v-model="search" aria-label="Tìm vật tư" placeholder="Tìm mã hoặc tên vật tư…" /><UiButton variant="outline" type="submit" class="stock-button" :disabled="busy||!company">Tìm</UiButton></form></div><DataTable :rows="stocks" :columns="stockColumns" :loading="busy" :empty="search?'Không tìm thấy vật tư phù hợp.':'Chưa có vật tư. Thêm danh mục trong Thiết lập kho.'" /><footer class="stock-pagination"><span>Tối đa 50 vật tư / trang</span><div><UiButton variant="outline" class="stock-button" :disabled="!start||busy" @click="start-=50;refresh()">← Trước</UiButton><UiButton variant="outline" class="stock-button" :disabled="!data?.has_more||busy" @click="start+=50;refresh()">Sau →</UiButton></div></footer></section>
   </template>
   <section v-if="tab==='history'" class="stock-panel"><div class="stock-panel-head"><div><h2>Phiếu gần đây</h2><p>Toàn công ty đã chọn · 20 phiếu kho và 10 phiếu kiểm kê gần nhất</p></div><UiButton variant="outline" class="stock-button" :disabled="busy" @click="refresh()">Cập nhật phiếu</UiButton></div><DataTable :rows="historyRows" :columns="historyColumns" :loading="busy" interactive @open="row=>openDocument(row.doctype,row.name)" /></section>
   <section v-if="tab==='setup'" class="stock-setup">
    <UiCard><span>01</span><h2>Nhóm vật tư</h2><p>Phân bón, thuốc bảo vệ thực vật, bao bì, nông cụ… Gom vật tư để dễ tìm và theo dõi.</p><UiButton variant="outline" class="stock-button" :disabled="!company||!session?.permissions['Item Group']" @click="openMaster('group')">+ Thêm nhóm vật tư</UiButton></UiCard>
    <UiCard><span>02</span><h2>Danh mục vật tư</h2><p>Chỉ cần mã, tên, nhóm và đơn vị tính. Thêm xong có thể chọn ngay khi lập phiếu.</p><UiButton variant="outline" class="stock-button" :disabled="!company||!session?.permissions.Item" @click="openMaster('item')">+ Thêm vật tư</UiButton></UiCard>
    <UiCard><span>03</span><h2>Kho của farm</h2><p>Đặt tên kho dễ nhận biết. Kho mới thuộc công ty {{company||'đang chọn'}} và bắt đầu với tồn bằng 0.</p><UiButton variant="outline" class="stock-button" :disabled="!company||!session?.permissions.Warehouse" @click="openMaster('warehouse')">+ Thêm kho</UiButton></UiCard>
    <div class="stock-setup-note"><h3>{{company?'Công ty: '+company:'Chưa có công ty vận hành'}}</h3><p>{{company?'Tạo nhóm, thêm vật tư và kho ngay tại đây. Khi hàng về, chọn Nhập kho để ghi nhận.':'Cần cấu hình công ty vận hành trước khi tạo danh mục kho.'}}</p></div>
   </section>
   <p class="stock-footnote">Phiếu nháp chưa làm thay đổi tồn. Tồn kho cập nhật sau khi phiếu được ghi sổ.</p>
  </main>
  <dialog ref="dialog" class="stock-dialog" @cancel="error=''">
   <form @submit.prevent="save"><header><div><p class="stock-kicker">PHIẾU KHO MỚI</p><h2>{{kinds[form.kind]}}</h2></div><UiButton variant="outline" type="button" class="stock-button" aria-label="Đóng" :disabled="saving" @click="dialog.close()">✕</UiButton></header><p class="stock-muted">{{company}} · {{form.kind==='count'?'Nhập số lượng đếm thực tế, không phải số chênh lệch.':'Số lượng tính theo đơn vị tồn kho của vật tư.'}}</p><p v-if="error" class="stock-error" role="alert">{{error}}</p>
    <section v-if="form.kind==='issue'" class="stock-issue-picker">
     <div class="stock-issue-tabs" role="tablist" aria-label="Hình thức xuất kho"><UiButton variant="outline" v-for="(title,mode) in issueTabs" :key="mode" type="button" role="tab" :aria-selected="form.issue_mode===mode" :class="{active:form.issue_mode===mode}" :disabled="saving" @click="changeIssueMode(mode)">{{title}}</UiButton></div>
     <p class="stock-muted">{{form.issue_mode==='Manual'?'Nhập vật tư, số lượng, nơi sử dụng và lý do xuất.':form.issue_mode==='Plan'?'Chọn kế hoạch đã duyệt. Dòng vật tư lấy từ nhu cầu đã duyệt của kế hoạch.':'Chọn yêu cầu cấp vật tư đã duyệt, gồm cả yêu cầu phát sinh ngoài kế hoạch.'}}</p>
     <label v-if="form.issue_mode!=='Manual'">{{form.issue_mode==='Plan'?'Kế hoạch đã duyệt':'Yêu cầu vật tư đã duyệt'}}<UiSelect v-model="issueSource" :disabled="issueLoading||saving" @change="selectIssueSource"><option value="">{{issueLoading?'Đang tải…':form.issue_mode==='Plan'?'Chọn kế hoạch':'Chọn yêu cầu'}}</option><option v-for="r in issueSources" :key="r.name" :value="r.name">{{r.name}} · {{r.date}}</option></UiSelect></label>
     <p v-if="form.issue_mode!=='Manual'&&!issueLoading&&!issueSources.length" class="stock-source-empty">{{form.issue_mode==='Plan'?'Chưa có kế hoạch đã duyệt trong công ty này.':'Chưa có yêu cầu cấp vật tư đã duyệt trong công ty này.'}}</p>
     <p v-if="issueNote" class="stock-muted">{{issueNote}}</p>
    </section><div class="stock-form-grid"><label>Ngày<UiInput v-model="form.posting_date" type="date" required /></label><label v-if="form.kind==='count'">Loại kiểm kê<UiSelect v-model="form.count_purpose"><option value="Stock Reconciliation">Kiểm kê định kỳ</option><option value="Opening Stock">Tồn đầu kỳ khi bắt đầu</option></UiSelect></label><label v-if="needsSource">Kho xuất<UiSelect v-model="form.source" required><option value="">Chọn kho</option><option v-for="w in data?.warehouses" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label><label v-if="needsTarget">{{form.kind==='count'?'Kho kiểm kê':'Kho nhận'}}<UiSelect v-model="form.target" required><option value="">Chọn kho</option><option v-for="w in data?.warehouses" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label></div><label v-if="form.kind==='issue'" class="stock-receiver">Người nhận vật tư<UiInput v-model="form.receiver" maxlength="140" placeholder="Tên người hoặc tổ nhận" required /></label><datalist id="stock-item-options"><option v-for="i in stocks" :key="i.name" :value="i.name">{{i.item_name}} · {{i.stock_uom}}</option></datalist><p v-if="form.kind==='issue'&&form.issue_mode!=='Manual'&&issueSource&&!issueLoading&&!form.lines.length" class="stock-source-empty">Nguồn này chưa có nhu cầu vật tư đã duyệt còn được cấp. Không có dòng nào để xuất.</p><div v-for="(row,index) in form.lines" :key="index" class="stock-line"><label>Vật tư<UiInput v-model="row.item" list="stock-item-options" placeholder="Mã vật tư" :readonly="form.kind==='issue'&&form.issue_mode!=='Manual'" required @change="chooseItem(row)" /><small>{{row.item_name||stocks.find(i=>i.name===row.item)?.item_name||'Nhập mã hoặc chọn từ gợi ý'}}</small></label><label>{{form.kind==='count'?'Tồn thực đếm':'Số lượng'}}<UiInput v-model.number="row.qty" type="number" :min="form.kind==='count'||(form.kind==='issue'&&form.issue_mode!=='Manual')?0:0.000001" :max="form.kind==='issue'&&form.issue_mode!=='Manual'?row.remaining_qty:undefined" step="any" required /><small>{{row.uom||stocks.find(i=>i.name===row.item)?.stock_uom||'Đơn vị tồn kho'}}</small></label><label v-if="form.kind==='issue'">Khu vực / lô sử dụng<UiInput v-model="row.area" maxlength="140" :readonly="form.issue_mode!=='Manual'&&row.fixed_area" placeholder="VD: Khu A / Lô A1" required /><small v-if="form.issue_mode!=='Manual'">Duyệt {{fmt(row.required_qty)}} · Đã cấp/giữ {{fmt(row.allocated_qty)}} · Còn {{fmt(row.remaining_qty)}}</small></label><UiButton variant="ghost" type="button" class="stock-remove" :disabled="form.lines.length===1||saving" aria-label="Xóa dòng vật tư" @click="form.lines.splice(index,1)">✕</UiButton></div><UiButton variant="outline" v-if="form.kind!=='issue'||form.issue_mode==='Manual'" type="button" class="stock-button" :disabled="form.lines.length>=100||saving" @click="form.lines.push({item:'',qty:1,area:''})">+ Thêm vật tư</UiButton><label v-if="form.kind!=='count'" class="stock-notes">{{form.kind==='issue'&&form.issue_mode==='Manual'?'Lý do xuất thủ công':'Ghi chú'}}<UiTextarea v-model="form.notes" maxlength="2000" :required="form.kind==='issue'&&form.issue_mode==='Manual'" placeholder="Mục đích cấp vật tư…"></UiTextarea></label><p class="stock-muted">Form này dùng cho vật tư thông thường, chưa hỗ trợ quản lý lô hoặc serial.</p><footer><span>Lưu nháp, sau đó kiểm tra và ghi sổ.</span><UiButton variant="default" type="submit" class="stock-button primary" :disabled="saving||issueLoading||!form.lines.length">{{saving?'Đang lưu…':'Lưu phiếu nháp →'}}</UiButton></footer></form>
  </dialog>
  <dialog ref="masterDialog" class="stock-dialog stock-master-dialog" @cancel="masterError=''">
   <form @submit.prevent="saveMaster"><header><div><p class="stock-kicker">DANH MỤC KHO</p><h2>{{masterTitles[masterKind]}}</h2></div><UiButton variant="outline" type="button" class="stock-button" aria-label="Đóng form danh mục" :disabled="masterBusy" @click="masterDialog.close()">✕</UiButton></header>
    <p class="stock-muted">{{masterKind==='warehouse'?'Công ty: '+company:'Dùng chung trong danh mục vật tư của Lotus.'}}</p><p v-if="masterError" role="alert" class="stock-error">{{masterError}}</p>
    <div class="stock-master-fields"><label v-if="masterKind==='item'">Mã vật tư<UiInput v-model="master.code" maxlength="140" placeholder="VD: PB-NPK-001" required /></label><label>{{masterKind==='item'?'Tên vật tư':masterKind==='group'?'Tên nhóm vật tư':'Tên kho'}}<UiInput v-model="master.name" maxlength="140" :placeholder="masterKind==='item'?'VD: Phân NPK 16-16-8':masterKind==='group'?'VD: Phân bón':'VD: Kho phân bón farm'" required /></label>
     <template v-if="masterKind==='item'"><label>Nhóm vật tư<UiSelect v-model="master.group" :required="!master.new_group" :disabled="!!master.new_group"><option value="">Chọn nhóm</option><option v-for="g in catalog.groups" :key="g.name" :value="g.name">{{g.name}}</option></UiSelect></label><label v-if="session?.permissions['Item Group']">Hoặc tạo nhóm mới<UiInput v-model="master.new_group" maxlength="140" placeholder="Để trống nếu dùng nhóm đã có" /></label><label>Đơn vị tính<UiSelect v-model="master.uom" required><option value="">Chọn đơn vị</option><optgroup label="Thường dùng"><option v-for="name in popularUoms" :key="name" :value="name">{{commonUnits[name]}}</option></optgroup><optgroup label="Đơn vị khác"><option v-for="u in catalog.uoms.filter(u=>!commonUnits[u.name])" :key="u.name" :value="u.name">{{u.name}}</option></optgroup></UiSelect></label><label>Ghi chú (không bắt buộc)<UiTextarea v-model="master.description" maxlength="2000" placeholder="Quy cách đóng gói, thông tin nhận biết…"></UiTextarea></label></template>
     <label v-if="masterKind==='group'&&catalog.groups.filter(g=>g.is_group).length>1">Nhóm cha<UiSelect v-model="master.parent" required><option v-for="g in catalog.groups.filter(g=>g.is_group)" :key="g.name" :value="g.name">{{g.name}}</option></UiSelect></label>
     <label v-if="masterKind==='warehouse'&&catalog.parents.length>1">Thuộc nhóm kho<UiSelect v-model="master.parent" required><option value="">Chọn nhóm kho</option><option v-for="w in catalog.parents" :key="w.name" :value="w.name">{{w.warehouse_name}}</option></UiSelect></label>
    </div><footer><span>{{masterKind==='item'?'Thêm danh mục chưa làm tăng tồn kho.':'Lưu xong có thể sử dụng ngay.'}}</span><UiButton variant="default" type="submit" class="stock-button primary" :disabled="masterBusy">{{masterBusy?'Đang lưu…':'Lưu '+(masterKind==='item'?'vật tư':masterKind==='group'?'nhóm':'kho')}}</UiButton></footer>
   </form>
  </dialog>
  <dialog ref="detailDialog" class="stock-dialog" @cancel="detailError=''">
   <form v-if="detail" @submit.prevent="postDocument"><header><div><p class="stock-kicker">CHI TIẾT PHIẾU</p><h2>{{detail.name}}</h2></div><UiButton variant="outline" type="button" class="stock-button" aria-label="Đóng chi tiết phiếu" :disabled="posting" @click="detailDialog.close()">✕</UiButton></header><p class="stock-muted">{{type(detail.kind)}} · {{detail.posting_date}} · {{detail.company}} · {{status(detail.docstatus)}}</p><p v-if="detailError" class="stock-error" role="alert">{{detailError}}</p><p v-if="detail.docstatus===1" class="stock-success" role="status">Phiếu đã ghi sổ. Tồn kho đã được cập nhật.</p>
   <DataTable :rows="detail.items" :columns="detailColumns" /><p v-if="detail.receiver" class="stock-muted">Người nhận: {{detail.receiver}} · {{issueTabs[detail.issue_mode]}}</p><p v-if="detail.notes" class="stock-muted">{{detail.notes}}</p>
   <footer v-if="detail.can_submit"><label class="stock-confirm"><input v-model="confirmPost" type="checkbox" required> Tôi đã kiểm tra phiếu. Ghi sổ sẽ cập nhật tồn kho.</label><UiButton variant="default" type="submit" class="stock-button primary" :disabled="posting||!confirmPost">{{posting?'Đang ghi sổ…':'Ghi sổ phiếu'}}</UiButton></footer><p v-else-if="detail.docstatus===0" class="stock-muted">Tài khoản chưa có quyền ghi sổ hoặc phiếu thuộc nghiệp vụ nâng cao chưa hỗ trợ ở đây.</p>
   </form>
  </dialog>
 </div>
</template>
